"""Этап synthesis: критерии выбора клиента, оценки 0–5 по 10 компаниям полного разбора.
Входы: data/sites_offers.csv, data/sites_prices.csv, data/wordstat_tops.csv, data/reviews_cards.csv,
data/traffic_channels_wide.csv, notes/raw_reviews/all_reviews.json, notes/raw_reviews/neg_coded.json.
Выходы: data/criteria.csv, data/criteria_text.csv, data/criteria_scores.csv.
Правила оценки и классы — notes/criteria_rules.md. Запуск: python3 -I build_criteria.py
"""
import csv, json, re, statistics as st
from collections import Counter, defaultdict

B = '/home/claude/zabory'
DATE = '2026-10-20'
CO = ['masterovit.ru', 'prof-zabory.ru', 'zaborkin.ru', 'zavodzaborov.ru', 'raduga-zaborov.ru',
      'zaborovo.ru', 'oblzabor.ru', 'dostup-zabor.ru', 'zaboroff.ru', 'pskzabor.ru']
K = dict(zip(['M', 'PZ', 'ZK', 'ZZ', 'RZ', 'ZV', 'OZ', 'DZ', 'ZF', 'PSK'], CO))
SECOND = {'sales.prof-zabory.ru': 'prof-zabory.ru', 'zabor-dlya-vseh.site': 'zavodzaborov.ru', 'p-z-z.ru': 'zaborovo.ru'}

def f1(x):
    return f'{x:.1f}'.replace('.', ',')

def fnum(x):
    return f'{x:,.0f}'.replace(',', ' ') if isinstance(x, (int, float)) else x

# ---------- отзывы ----------
allr = json.load(open(f'{B}/notes/raw_reviews/all_reviews.json', encoding='utf-8'))
neg_all, pos_all = [], []
ya_texts, ya_neg, ya_reply = Counter(), Counter(), Counter()
for x in allr:
    if x['company'] not in CO or not (x['text'] or '').strip():
        continue
    s = int(float(x['stars'] or 0)); t = x['text'].lower()
    if s <= 3:
        neg_all.append(t)
    elif len(x['text'].strip()) >= 15:
        pos_all.append(t)
    if x['platform'] == 'Яндекс Карты':
        ya_texts[x['company']] += 1
        if s <= 3: ya_neg[x['company']] += 1
        if (x.get('reply') or '').strip(): ya_reply[x['company']] += 1
assert len(neg_all) == 851 and len(pos_all) == 3985, (len(neg_all), len(pos_all))
coded = json.load(open(f'{B}/notes/raw_reviews/neg_coded.json', encoding='utf-8'))['neg']
theme_ya = defaultdict(Counter)      # компания -> тема -> число негативных отзывов Яндекс Карт
theme_mkt = Counter()                 # тема -> число по 10 компаниям, все площадки (n=851)
for x in coded:
    if x['company'] not in CO: continue
    for th in x['themes']:
        theme_mkt[th] += 1
        if x['platform'] == 'Яндекс Карты': theme_ya[x['company']][th] += 1
POS_THEME = {}
for x in csv.DictReader(open(f'{B}/data/reviews_themes.csv', encoding='utf-8')):
    if x['polarity'] == 'позитив (4–5★), весь массив':
        POS_THEME[x['theme']] = int(x['n_reviews_with_theme'])

def rx_share(rx, texts):
    r = re.compile(rx); return sum(1 for t in texts if r.search(t))

# ---------- офферы (h1 + подзаголовок + УТП + акции), по компаниям ----------
offers = defaultdict(str)
for x in csv.DictReader(open(f'{B}/data/sites_offers.csv', encoding='utf-8')):
    c = SECOND.get(x['domain'], x['domain'])
    offers[c] += ' ' + ' '.join([x['h1_first_screen'], x['subheadline'], x['usp'], x['promos']]).lower()

# ---------- уточнения запросов (49 формулировок, без строк «не снято») ----------
queries = [x['refinement'].lower() for x in csv.DictReader(open(f'{B}/data/wordstat_tops.csv', encoding='utf-8'))
           if x['type'] != 'не снято']
assert len(queries) == 49, len(queries)

# ---------- вычисляемые клетки ----------
def rate_score(rate):           # жалоб темы на 100 текстов Яндекс Карт
    for lim, sc in [(1, 5), (2, 4), (4, 3), (7, 2), (10, 1)]:
        if rate <= lim: return sc
    return 0

def review_rate(company, theme):
    n = ya_texts[company]; k = theme_ya[company][theme]
    return 100 * k / n, k, n

auto = {}
# C01 доля 1–3★ в текстах Яндекс Карт
cells = {}
for c in CO:
    sh = round(100 * ya_neg[c] / ya_texts[c], 1)
    sc = 5 if sh <= 5 else 4 if sh <= 8 else 3 if sh <= 13 else 2 if sh <= 20 else 1 if sh <= 28 else 0
    note = {'zaborovo.ru': '; 4 пятёрки с текстом от отдела контроля качества', 'pskzabor.ru': '; 9,9% пятёрок с совпадающими фразами (2ГИС)',
            'oblzabor.ru': '; малая база', 'zaborkin.ru': '; в 2ГИС 1,6% (189 оценок)'}.get(c, '')
    cells[c] = (sc, f'{f1(sh)}% 1–3★ (n={ya_texts[c]}){note}')
auto['C01'] = cells
# C02 число оценок Яндекс Карт (сумма по карточкам)
cnt = Counter()
for x in csv.DictReader(open(f'{B}/data/reviews_cards.csv', encoding='utf-8')):
    if x['platform'] == 'Яндекс Карты' and x['company'] in CO and x['ratings_count']:
        cnt[x['company']] += int(float(x['ratings_count']))
cells = {}
for c in CO:
    v = cnt[c]; sc = 5 if v >= 1000 else 4 if v >= 500 else 3 if v >= 300 else 2 if v >= 150 else 1 if v > 0 else 0
    cells[c] = (sc, f'оценок на Яндекс Картах: {fnum(v)}')
auto['C02'] = cells
# C07 цена профнастила «от» с монтажом (главный сайт)
price = {}
for x in csv.DictReader(open(f'{B}/data/sites_prices.csv', encoding='utf-8')):
    if x['domain'] in CO and x['product'] == 'профнастил' and x['domain'] not in price:
        price[x['domain']] = int(x['price_from_rub'])
pmin, pmax = min(price.values()), max(price.values())
second = {'zavodzaborov.ru': '; второй сайт 1 376 ₽', 'prof-zabory.ru': '; лендинг 1 490 ₽, таблица 1,5 м 2 095 ₽',
          'raduga-zaborov.ru': '; на странице цен 2 100 ₽', 'masterovit.ru': '; на той же странице 1 960 и 2 004 ₽'}
auto['C07'] = {c: (round(5 * (pmax - price[c]) / (pmax - pmin)), f'от {fnum(price[c])} ₽/п.м.{second.get(c, "")}') for c in CO}
PRICE_MEDIAN = st.median(price.values())
# C39 визиты в месяц (Similarweb, июль–сентябрь 2026)
vis = {x['domain']: int(x['visits_3m']) / 3 for x in csv.DictReader(open(f'{B}/data/traffic_channels_wide.csv', encoding='utf-8'))}
def vis_sc(v):
    return 5 if v >= 100000 else 4 if v >= 30000 else 3 if v >= 10000 else 2 if v >= 5000 else 1
auto['C39'] = {c: (vis_sc(vis[c]), f'визитов в месяц: {fnum(round(vis[c]))}') for c in CO}
# C40 доля ответов компании на тексты Яндекс Карт
def rep_sc(p):
    return 5 if p >= 97 else 4 if p >= 90 else 3 if p >= 80 else 2 if p >= 60 else 1
auto['C40'] = {c: (rep_sc(round(100 * ya_reply[c] / ya_texts[c])), f'ответ на {round(100 * ya_reply[c] / ya_texts[c])}% отзывов (n={ya_texts[c]})') for c in CO}
# C41 качество монтажа: жалоб на 100 текстов Яндекс Карт
cells = {}
for c in CO:
    r, k, n = review_rate(c, 'качество_монтажа'); r = round(r, 1)
    cells[c] = (rate_score(r), f'жалоб на монтаж: {f1(r)} на 100 отзывов ({k} из {n})')
auto['C41'] = cells

