W_REV, W_Q, IMPORTANT = 0.7, 0.3, 10   # вес = 100 × (0,7 × r / r_max + 0,3 × q / q_max); «важен» — вес ≥ 10

def count(spec, base):
    if not spec: return 0
    kind, v = spec
    if kind == T: return theme_mkt[v]
    if kind == PT: return POS_THEME[v]
    return rx_share(v, base)

pre = []
for cid, grp, name, nspec, pspec, rx_off, rx_q, measure, src in DEF:
    neg_n = count(nspec, neg_all); pos_n = count(pspec, pos_all)
    r = max(neg_n / 851, pos_n / 3985)
    q_n = sum(1 for q in queries if re.search(rx_q, q)) if rx_q else 0
    off_n = sum(1 for c in CO if re.search(rx_off, offers[c])) if rx_off else 0
    pre.append([cid, grp, name, neg_n, pos_n, r, q_n, off_n, measure, src])
r_max = max(x[5] for x in pre); q_max = max(x[6] for x in pre)

crit_rows, text_rows, score, promise = [], [], {}, {}
for cid, grp, name, neg_n, pos_n, r, q_n, off_n, measure, src in pre:
    w = round(100 * (W_REV * r / r_max + W_Q * q_n / q_max), 1)
    if cid in auto:
        cells = auto[cid]
    else:
        cells = {}
        for k, c in K.items():
            sc, fact = S[cid][k]
            if cid in COMBO:
                rr, kk, nn = review_rate(c, COMBO[cid]); rr = round(rr, 1)
                sc = int((sc + rate_score(rr)) / 2 + 0.5)
                fact = f'{fact}; жалоб по теме: {f1(rr)} на 100 отзывов ({kk} из {nn})'
            cells[c] = (sc, fact)
    score[cid] = {c: cells[c][0] for c in CO}
    if cid in ('C01', 'C41'):
        promise[cid] = {c: 'н/п' for c in CO}
    elif cid in auto:
        promise[cid] = dict(score[cid])
    else:
        promise[cid] = {c: S[cid][k][0] for k, c in K.items()}
    cov = sum(1 for c in CO if cells[c][0] >= 3)
    if w < IMPORTANT: cls = 'второстепенный'
    elif cov >= 8: cls = 'обязательный'
    elif cov >= 4: cls = 'ключевой'
    else: cls = 'свободный'
    best = max(cells[c][0] for c in CO)
    crit_rows.append({'id': cid, 'group': grp, 'criterion': name, 'class': cls, 'weight': w,
                      'voice_measure': measure,
                      'reviews_neg_n': neg_n, 'reviews_neg_base': 851, 'reviews_pos_n': pos_n, 'reviews_pos_base': 3985,
                      'reviews_share_max_pct': round(100 * r, 1), 'queries_n': q_n, 'queries_base': 49,
                      'market_offers_n': off_n, 'market_offers_base': 10,
                      'companies_score_ge3': cov, 'best_score_on_market': best,
                      'leaders': ', '.join(c for c in CO if cells[c][0] == best), 'source': src, 'date': DATE})
    row = {'id': cid, 'criterion': name}
    for c in CO: row[c] = cells[c][1]
    row['source'] = src; row['date'] = DATE
    text_rows.append(row)

crit_rows.sort(key=lambda x: -x['weight'])
for i, x in enumerate(crit_rows, 1): x['rank'] = i
W = {x['id']: x['weight'] for x in crit_rows}
order = [x['id'] for x in crit_rows]
name_of = {x['id']: x['criterion'] for x in crit_rows}
cls_of = {x['id']: x['class'] for x in crit_rows}

def wcsv(path, rows, fields):
    with open(path, 'w', encoding='utf-8', newline='') as f:
        w = csv.DictWriter(f, fieldnames=fields); w.writeheader(); w.writerows(rows)

wcsv(f'{B}/data/criteria.csv', crit_rows, ['rank', 'id', 'group', 'criterion', 'class', 'weight', 'voice_measure', 'reviews_neg_n', 'reviews_neg_base',
     'reviews_pos_n', 'reviews_pos_base', 'reviews_share_max_pct', 'queries_n', 'queries_base', 'market_offers_n', 'market_offers_base',
     'companies_score_ge3', 'best_score_on_market', 'leaders', 'source', 'date'])
text_rows.sort(key=lambda x: order.index(x['id']))
wcsv(f'{B}/data/criteria_text.csv', text_rows, ['id', 'criterion'] + CO + ['source', 'date'])
srows = []
for cid in order:
    row = {'id': cid, 'criterion': name_of[cid], 'class': cls_of[cid], 'weight': W[cid]}
    row.update(score[cid]); srows.append(row)
N = len(order)
tot = {'id': 'ИТОГ', 'criterion': f'сумма баллов (макс. {5 * N})', 'class': '—', 'weight': '—'}
wav = {'id': 'ИТОГ_ВЗВ', 'criterion': 'взвешенный балл 0–5 = Σ(балл × вес) / Σ вес', 'class': '—', 'weight': round(sum(W.values()), 1)}
key = {'id': 'ИТОГ_КЛЮЧ', 'criterion': 'взвешенный балл 0–5 по ключевым и свободным', 'class': '—', 'weight': '—'}
kk = [c for c in order if cls_of[c] in ('ключевой', 'свободный')]
for c in CO:
    tot[c] = sum(score[x][c] for x in order)
    wav[c] = round(sum(score[x][c] * W[x] for x in order) / sum(W.values()), 2)
    key[c] = round(sum(score[x][c] * W[x] for x in kk) / sum(W[x] for x in kk), 2)
srows += [tot, wav, key]
wcsv(f'{B}/data/criteria_scores.csv', srows, ['id', 'criterion', 'class', 'weight'] + CO)

# оценки только по обещанию на сайте (без жалоб в отзывах) — для сравнения обещаний с целевым оффером
prow = []
for cid in order:
    row = {'id': cid, 'criterion': name_of[cid], 'class': cls_of[cid], 'weight': W[cid], 'combined_with_reviews': 'да' if cid in COMBO else ('только отзывы' if cid in ('C01', 'C41') else 'нет')}
    row.update(promise[cid]); prow.append(row)
wcsv(f'{B}/data/criteria_scores_promise.csv', prow, ['id', 'criterion', 'class', 'weight', 'combined_with_reviews'] + CO)

